import numpy as np
import pandas as pd

def phi(driver):
    initial_region_max = 6.0
    activation_end = 10.0
    if driver <= initial_region_max:
        return 0.0
    elif driver >= activation_end:
        return 1.0
    else:
        t = (driver - initial_region_max) / (activation_end - initial_region_max)
        return t**2 * (3 - 2*t)

def base_mean(driver, gain, scale):
    return 10 + gain * (1 - np.exp(-driver / scale))

def base_sd(driver, noise_base=0.65, noise_high_slope=0.22):
    return noise_base + noise_high_slope * max(driver - 5, 0)

def model(regime, n, seed):
    target_line = 2
    line = regime.config.get('line')
    driver = regime.config.get('driver')
    rng = np.random.default_rng(seed)

    triplets = [(11.5, 3.4, 2.25), (11.5, 3.8, 2.0)]
    triplet_weights = [0.5987108427646576, 0.40128915723534236]
    scenario_probs = {'maintain': 0.84, 'revise': 0.08, 'doubt': 0.08}
    scenario_names = list(scenario_probs.keys())
    scenario_cum = np.cumsum(list(scenario_probs.values()))

    # Pre-sample parameters for n draws
    triplet_idx = rng.choice(len(triplets), size=n, p=triplet_weights)
    scenario_u = rng.random(size=n)
    scenario = np.zeros(n, dtype=int)  # 0 maintain,1 revise,2 doubt
    scenario[scenario_u < scenario_cum[0]] = 0
    scenario[(scenario_u >= scenario_cum[0]) & (scenario_u < scenario_cum[1])] = 1
    scenario[scenario_u >= scenario_cum[1]] = 2
    stratum = rng.choice([-1, 1], size=n)  # used only for doubt

    outcomes = np.zeros(n)
    for i in range(n):
        gain, scale, amplitude = triplets[triplet_idx[i]]
        b_mean = base_mean(driver, gain, scale)
        b_sd = base_sd(driver)
        phi_val = phi(driver)
        if line == target_line:
            if scenario[i] == 0:
                mean = b_mean
            elif scenario[i] == 1:
                mean = b_mean - amplitude * phi_val
            else:
                mean = b_mean + stratum[i] * amplitude * phi_val
        else:
            mean = b_mean
        outcomes[i] = rng.normal(mean, b_sd)
    return pd.DataFrame({'outcome': outcomes})
"""

